import { render as provider } from '@dropins/storefront-cart/render.js';
import { CartSummaryGrid } from '@dropins/storefront-cart/containers/CartSummaryGrid.js';

// block = document.getElementById('@dropins/CartSummaryGrid') when mounting to a block
await provider.render(CartSummaryGrid, {
  routeProduct: (item) => {
    return `${item.url.categories.join('/')}/${item.url.urlKey}`;
  },
  routeEmptyCartCTA: () => '#empty-cart',
})(block);

import { render as provider } from '@dropins/storefront-cart/render.js';
import { OrderSummaryLine } from '@dropins/storefront-cart/containers/OrderSummaryLine.js';

// In updateLineItems or a slot - lineItem from cart/order summary data
const label = lineItem.label ?? 'Subtotal';
const price = document.createElement('span');
price.textContent = lineItem.formattedValue ?? String(lineItem.value ?? 0);
await provider.render(OrderSummaryLine, {
  label,
  price,
  classSuffixes: [lineItem.key]
})(block);
